/** One injected stylesheet (scoped under `.dsh-rewind-*`). */
export declare const STYLE = "\r\n.dsh-rewind-btn {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n  /* The neighbouring action buttons scale by this delta too. */\r\n  width: calc(28px + var(--dsh-content-font-delta, 0px));\r\n  height: calc(28px + var(--dsh-content-font-delta, 0px));\r\n  padding: 6px;\r\n  border: none;\r\n  border-radius: var(--dsw-radius-sm, 8px);\r\n  background: transparent;\r\n  color: var(--dsw-alias-label-tertiary);\r\n  cursor: pointer;\r\n}\r\n.dsh-rewind-btn svg {\r\n  width: calc(15px + var(--dsh-content-font-delta, 0px));\r\n  height: calc(15px + var(--dsh-content-font-delta, 0px));\r\n}\r\n@media (hover: hover) {\r\n  .dsh-rewind-btn:hover {\r\n    background: var(--dsw-alias-interactive-bg-hover);\r\n    color: var(--dsw-alias-label-secondary);\r\n  }\r\n}\r\n\r\n.dsh-rewind-popover {\r\n  position: fixed;\r\n  z-index: 1100;\r\n  box-sizing: border-box;\r\n  width: min(300px, calc(100vw - 24px));\r\n  padding: 16px;\r\n  border: 0;\r\n  border-radius: var(--dsw-radius-lg);\r\n  background: var(--dsw-specific-menu, var(--dsw-alias-bg-layer-3));\r\n  backdrop-filter: var(--dsw-menu-backdrop-filter);\r\n  isolation: isolate;\r\n  --dsw-elevation-stroke-color: var(--dsw-alias-border-l1);\r\n  /* Elevated surface: match the menu cards' l2 scrollbar tokens. */\r\n  --dsh-scrollbar-thumb: var(--dsw-alias-scrollbar-bg-l2);\r\n  --dsh-scrollbar-thumb-hover: var(--dsw-alias-scrollbar-hover-l2);\r\n  box-shadow: var(--dsw-elevation-prominent);\r\n  font-size: 12px;\r\n  line-height: 18px;\r\n  color: var(--dsw-alias-label-primary);\r\n}\r\n.dsh-rewind-popover-title {\r\n  font-size: 12px;\r\n  font-weight: 500;\r\n  line-height: 18px;\r\n}\r\n.dsh-rewind-popover-target {\r\n  margin: 2px 0 10px;\r\n  font-size: 12px;\r\n  line-height: 18px;\r\n  color: var(--dsw-alias-label-tertiary);\r\n  word-break: break-all;\r\n  /* The full message sits above the popover; two lines are enough context. */\r\n  display: -webkit-box;\r\n  -webkit-box-orient: vertical;\r\n  -webkit-line-clamp: 2;\r\n  overflow: hidden;\r\n}\r\n.dsh-rewind-popover-option {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 2px;\r\n  width: 100%;\r\n  margin: 0 0 2px;\r\n  padding: 6px 8px;\r\n  border: 0;\r\n  border-radius: 8px;\r\n  background: transparent;\r\n  color: inherit;\r\n  font: inherit;\r\n  text-align: left;\r\n  cursor: pointer;\r\n}\r\n.dsh-rewind-popover-option:hover {\r\n  background: var(--dsw-alias-interactive-bg-hover);\r\n}\r\n/* Arrow navigation moves real focus, so the focused row carries the pointer's\r\n   fill and the browser ring is suppressed: in dark mode the UA two-tone ring\r\n   draws its dark half against the filled row and reads as a residue edge (the\r\n   harness Menu suppresses it the same way). */\r\n.dsh-rewind-popover-option:focus-visible:not(:disabled) {\r\n  background: var(--dsw-alias-interactive-bg-hover);\r\n  outline: none;\r\n}\r\n.dsh-rewind-popover-option:disabled {\r\n  opacity: 0.4;\r\n  cursor: default;\r\n}\r\n.dsh-rewind-popover-option-label {\r\n  font-weight: 500;\r\n}\r\n.dsh-rewind-popover-option-hint {\r\n  font-size: 12px;\r\n  line-height: 16px;\r\n  color: var(--dsw-alias-label-tertiary);\r\n}\r\n.dsh-rewind-popover-impact {\r\n  margin: 4px 0 10px;\r\n  padding: 8px 10px;\r\n  border-radius: 8px;\r\n  background: var(--dsw-alias-interactive-bg-hover);\r\n  font-size: 12px;\r\n  line-height: 16px;\r\n  color: var(--dsw-alias-label-secondary);\r\n  white-space: pre-wrap;\r\n  max-height: 160px;\r\n  overflow: auto;\r\n}\r\n/* Inline impact list in the mode step: the user chooses \"conversation and\r\n   files\" already knowing WHICH files that is, without opening the confirm\r\n   step. Same surface as the impact panel, one size smaller. */\r\n.dsh-rewind-popover-files {\r\n  margin: 0 0 8px;\r\n  padding: 6px 8px;\r\n  border-radius: 8px;\r\n  background: var(--dsw-alias-interactive-bg-hover);\r\n  font-size: 12px;\r\n  line-height: 16px;\r\n  color: var(--dsw-alias-label-secondary);\r\n  white-space: pre-wrap;\r\n  word-break: break-all;\r\n  max-height: 96px;\r\n  overflow: auto;\r\n}\r\n.dsh-rewind-popover-note {\r\n  margin-top: 6px;\r\n  font-size: 11px;\r\n  line-height: 15px;\r\n  color: var(--dsw-alias-label-tertiary);\r\n}\r\n.dsh-rewind-popover-actions {\r\n  display: flex;\r\n  justify-content: flex-end;\r\n  gap: 8px;\r\n  margin-top: 8px;\r\n}\r\n.dsh-rewind-popover-primary,\r\n.dsh-rewind-popover-ghost {\r\n  height: 28px;\r\n  padding: 0 10px;\r\n  border: none;\r\n  border-radius: 8px;\r\n  font: inherit;\r\n  cursor: pointer;\r\n}\r\n.dsh-rewind-popover-primary {\r\n  background: var(--dsw-alias-button-primary-fill);\r\n  color: var(--dsw-alias-label-primary-foreground);\r\n}\r\n.dsh-rewind-popover-primary:hover:not(:disabled) {\r\n  background: var(--dsw-alias-button-primary-hover);\r\n}\r\n.dsh-rewind-popover-primary:disabled {\r\n  opacity: 0.4;\r\n  cursor: default;\r\n}\r\n.dsh-rewind-popover-ghost {\r\n  background: transparent;\r\n  color: var(--dsw-alias-label-secondary);\r\n}\r\n.dsh-rewind-popover-ghost:hover {\r\n  background: var(--dsw-alias-interactive-bg-hover);\r\n}\r\n.dsh-rewind-popover-ghost:active {\r\n  background: var(--dsw-alias-interactive-bg-active);\r\n}\r\n\r\n.dsh-rewind-guard-hint {\r\n  position: fixed;\r\n  z-index: 1000;\r\n  max-width: min(440px, calc(100vw - 24px));\r\n  padding: 8px 12px;\r\n  border: 0;\r\n  border-radius: var(--dsw-radius-md);\r\n  background: var(--dsw-specific-menu, var(--dsw-alias-bg-layer-3));\r\n  backdrop-filter: var(--dsw-menu-backdrop-filter);\r\n  isolation: isolate;\r\n  --dsw-elevation-stroke-color: var(--dsw-alias-border-l1);\r\n  box-shadow: var(--dsw-elevation-panel);\r\n  font-size: 13px;\r\n  line-height: 18px;\r\n  color: var(--dsw-alias-label-primary);\r\n  pointer-events: none;\r\n}\r\n\r\n/* ---- Plugin configuration form ---- */\r\n/* Only the card's own controls: the two switch rows, their hints, and the divider. */\r\n.dsh-rewind-settings-divider {\r\n  border-top: 1px solid var(--dsw-alias-border-l2);\r\n}\r\n.dsh-rewind-settings-section {\r\n  display: grid;\r\n  gap: 6px;\r\n  padding: 12px 0;\r\n}\r\n.dsh-rewind-settings-toggle-row {\r\n  display: flex;\r\n  align-items: flex-start;\r\n  justify-content: space-between;\r\n  gap: 16px;\r\n  font-size: 13px;\r\n  line-height: 1.5;\r\n  color: var(--dsw-alias-label-primary);\r\n}\r\n.dsh-rewind-settings-toggle-label {\r\n  flex: 1;\r\n  min-width: 0;\r\n}\r\n.dsh-rewind-settings-hint {\r\n  margin: 0;\r\n  font-size: 12px;\r\n  line-height: 1.5;\r\n  color: var(--dsw-alias-label-tertiary);\r\n}\r\n";
